import csv
import math


def parse_amount(raw):
    if raw is None:
        return None
    if isinstance(raw, bool):
        raise TypeError("amount must not be bool")
    if isinstance(raw, str) and raw.strip().lower() in {"", "null"}:
        return None
    try:
        value = float(raw)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"invalid amount: {raw!r}") from exc
    if not math.isfinite(value):
        raise ValueError("amount must be finite")
    return value


def total_amounts(csv_text):
    rows = csv.reader(csv_text.splitlines())
    header = next(rows, None)
    if header is None:
        return 0.0
    total = 0.0
    for row_number, row in enumerate(rows, start=2):
        if len(row) < 2:
            raise ValueError(f"row {row_number} has no amount field")
        value = parse_amount(row[1])
        if value is not None:
            total += value
    return total

import unittest

import processor


class AmountImportTests(unittest.TestCase):
    def test_missing_values_become_none(self):
        for value in (None, "", "  ", "null", " NULL "):
            with self.subTest(value=value):
                self.assertIsNone(processor.parse_amount(value))

    def test_zero_is_preserved(self):
        self.assertEqual(processor.parse_amount("0"), 0.0)

    def test_finite_number_is_converted(self):
        self.assertEqual(processor.parse_amount("2.50"), 2.5)

    def test_invalid_nonempty_text_is_rejected(self):
        with self.assertRaises(ValueError):
            processor.parse_amount("oops")

    def test_nonfinite_values_are_rejected(self):
        for value in ("nan", "inf", "-inf"):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    processor.parse_amount(value)

    def test_bool_is_rejected(self):
        with self.assertRaises(TypeError):
            processor.parse_amount(True)

    def test_nonstring_numeric_input_is_finite_and_converted(self):
        self.assertEqual(processor.parse_amount(2), 2.0)

    def test_total_ignores_missing_but_keeps_zero(self):
        data = """expense,amount
coffee,
refund,0
meal,2.50
"""
        self.assertEqual(processor.total_amounts(data), 2.5)

    def test_empty_and_header_only_data_are_zero(self):
        self.assertEqual(processor.total_amounts(""), 0.0)
        self.assertEqual(processor.total_amounts("expense,amount\n"), 0.0)

    def test_short_csv_row_is_rejected(self):
        with self.assertRaises(ValueError):
            processor.total_amounts("expense,amount\ncoffee\n")


if __name__ == "__main__":
    unittest.main()
